{
  "hypotheses": [
    {
      "name": "Contrarian Innovation",
      "mechanism": "Combining EarningsSurprise and IntanBM, this factor captures firms with unexpected earnings alongside robust intangible asset backing, potentially benefiting from market mispricing due to information asymmetry.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "EarningsSurprise"},
          {"weight": 0.5, "primitive": "IntanBM"}
        ],
        "regime": "MKT_TRAILING_12M_DOWN",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
        {"type": "size_segment", "segment": "small", "direction": "stronger"},
        {"type": "international", "region": "emerging", "direction": "same_sign"}
      ],
      "expected_annualized_sharpe": 0.9,
      "expected_decay_half_life_months": 36
    },
    {
      "name": "Leverage Momentum",
      "mechanism": "The Leverage and Mom12mOffSeason indicators together capture firms with recent momentum but moderated by leverage effects, potentially reflecting the market's risk adjustment.",
      "expression": {
        "terms": [
          {"weight": -0.5, "primitive": "Leverage"},
          {"weight": 1.0, "primitive": "Mom12mOffSeason"}
        ],
        "regime": "TERM_SPREAD_POSITIVE",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.7,
      "expected_decay_half_life_months": 24
    },
    {
      "name": "Volatility Consistency",
      "mechanism": "By combining IdioVolAHT and EarningsConsistency, it identifies stable earnings amidst market noise, suggesting a premium for firms maintaining performance consistency.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "IdioVolAHT"},
          {"weight": 0.5, "primitive": "EarningsConsistency"}
        ],
        "regime": "VIX_BELOW_TRAILING_MEDIAN",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
        {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 1.1,
      "expected_decay_half_life_months": 48
    },
    {
      "name": "Growth Surprise",
      "mechanism": "Integrating AssetGrowth and RevenueSurprise captures companies with unexpected growth acceleration, potentially reflecting underappreciated operational improvements.",
      "expression": {
        "terms": [
          {"weight": 0.5, "primitive": "AssetGrowth"},
          {"weight": 1.0, "primitive": "RevenueSurprise"}
        ],
        "regime": "MKT_TRAILING_12M_UP",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
        {"type": "size_segment", "segment": "micro", "direction": "stronger"},
        {"type": "correlation", "primitive": "RevenueSurprise", "bound": "above", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.8,
      "expected_decay_half_life_months": 36
    },
    {
      "name": "Defensive Growth",
      "mechanism": "Combining Cash and Growth in Advertising Expenses (GrAdExp) highlights firms with a defensive cash position that strategically invest in growth, managing market volatility.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "Cash"},
          {"weight": 0.5, "primitive": "GrAdExp"}
        ],
        "regime": null,
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "size_segment", "segment": "mega", "direction": "stronger"},
        {"type": "international", "region": "emerging", "direction": "same_sign"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 0.9,
      "expected_decay_half_life_months": 48
    },
    {
      "name": "Risk-Adjusted Profitability",
      "mechanism": "By combining ROE and BetaFP, it targets firms maintaining high returns on equity adjusted for risk, suggesting efficient capital allocation under varying market conditions.",
      "expression": {
        "terms": [
          {"weight": -0.5, "primitive": "BetaFP"},
          {"weight": 1.0, "primitive": "RoE"}
        ],
        "regime": "TERM_SPREAD_NEGATIVE",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "correlation", "primitive": "RoE", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.75,
      "expected_decay_half_life_months": 24
    },
    {
      "name": "Consumer Sentiment Resilience",
      "mechanism": "Integrating Consumer Momentum (CustomerMomentum) and Analyst Value captures firms benefiting from positive consumer sentiment and analyst recognition, withstanding market downturns.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "CustomerMomentum"},
          {"weight": 0.5, "primitive": "AnalystValue"}
        ],
        "regime": "VIX_ABOVE_TRAILING_MEDIAN",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
        {"type": "size_segment", "segment": "small", "direction": "stronger"},
        {"type": "international", "region": "developed_ex_us", "direction": "opposite_sign"}
      ],
      "expected_annualized_sharpe": 0.85,
      "expected_decay_half_life_months": 30
    },
    {
      "name": "Operational Efficiency",
      "mechanism": "By combining Operating Profits/Book Equity (OperProf) and Change in Asset Turnover, the factor identifies firms enhancing operational efficiency, potentially signaling sustained competitive advantage.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "OperProf"},
          {"weight": 0.5, "primitive": "ChAssetTurnover"}
        ],
        "regime": null,
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "international", "region": "emerging", "direction": "same_sign"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 1.0,
      "expected_decay_half_life_months": 36
    }
  ]
}
